#!/usr/bin/env python3
from pathlib import Path
import json,re,html
ROOT=Path('.')
PAGE=ROOT/'shows/comedy/carrot-top/index.html'
DATE='2026-09-09'; FRESH='September 2026'; VENUE='Atrium Showroom at Luxor'; ADDRESS='3900 S Las Vegas Blvd, Las Vegas, NV 89119'
old=PAGE.read_text(encoding='utf-8')

def ld_objects(src):
    out=[]
    for raw in re.findall(r'<script type="application/ld\+json">(.*?)</script>',src,re.S):
        try: out.append(json.loads(raw))
        except Exception: pass
    return out
lds=ld_objects(old)
faq=next((x for x in lds if x.get('@type')=='FAQPage'),{'@context':'https://schema.org','@type':'FAQPage','mainEntity':[]})
video=next((x for x in lds if x.get('@type')=='VideoObject'),None)

# Source-of-truth fact alignment.
db_path=ROOT/'data/show-database.json'; db=json.loads(db_path.read_text(encoding='utf-8'))
rec=next(r for r in db['records'] if r['slug']=='carrot-top')
rec['venue']=VENUE; rec['showroom']='Atrium Showroom'; rec['verified_on']=DATE; rec['freshness_label']=FRESH
if rec.get('spotlight'):
    rec['spotlight']['location']=VENUE
    rec['spotlight']['age_label']='16+'
db['updated_on']=DATE
db_path.write_text(json.dumps(db,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
price=rec['our_price']; regular=rec.get('regular_price'); runtime=rec['runtime_minutes']; ticket=rec['ticket_url']; age='16+'; schedule=rec['schedule_summary']

# Relevant catalog venue normalization for Carrot Top only.
for p in [ROOT/'shows/comedy/index.html',ROOT/'index.html',ROOT/'venues/excalibur-luxor-mandalay-bay/index.html']:
    if not p.exists(): continue
    t=p.read_text(encoding='utf-8')
    t=re.sub(r"(slug:'carrot-top'[^\n]*?venue:)'[^']*'",lambda m:m.group(1)+"'Atrium Showroom at Luxor'",t)
    t=t.replace('Carrot Top</h3><div class="sc-venue">📍 Atrium Theater</div>','Carrot Top</h3><div class="sc-venue">📍 Atrium Showroom</div>')
    p.write_text(t,encoding='utf-8')

# Shared Atrium Showroom geometry: physical room only, reusable for Fantasy later.
def row_path(y,w,h,bow):
    cx=350; l=cx-w/2; r=cx+w/2
    return f'M {l:.1f} {y:.1f} Q {cx:.1f} {y-bow:.1f} {r:.1f} {y:.1f} L {r:.1f} {y+h:.1f} Q {cx:.1f} {y+h-bow:.1f} {l:.1f} {y+h:.1f} Z'
sections=[
 {'id':'reserved-1','label':'Reserved 1','rows':['A','B','C'],'color':'#ff2e7e','description':'Reserved 1 is the closest seating block to the stage, covering rows A through C.'},
 {'id':'reserved-2','label':'Reserved 2','rows':['D','E','F','G','H','I','J'],'color':'#7c3aed','description':'Reserved 2 is the large middle seating block, covering rows D through J.'},
 {'id':'reserved-3','label':'Reserved 3','rows':['K','L'],'color':'#0fb5c9','description':'Reserved 3 sits behind the main middle block, covering rows K and L.'},
 {'id':'reserved-4','label':'Reserved 4','rows':['M'],'color':'#159b8c','description':'Reserved 4 is the rear-most seating band, row M.'}
]
rows=[]
settings={
 'A':(560,360,34,30),'B':(522,420,34,30),'C':(484,480,34,30),
 'D':(424,515,34,26),'E':(386,535,34,25),'F':(348,550,34,24),'G':(310,565,34,23),'H':(272,578,34,22),'I':(234,590,34,21),'J':(196,602,34,20),
 'K':(132,618,36,18),'L':(92,634,36,17),'M':(28,652,42,15)
}
for s in sections:
    srows=[]
    for letter in s['rows']:
        y,w,h,b=settings[letter]; item={'label':letter,'path':row_path(y,w,h,b)}; srows.append(item); rows.append((s,item))
    s['row_slabs']=srows
layout={'version':1,'venue':VENUE,'address':ADDRESS,'viewBox':'0 0 700 760','stage':{'path':'M 235 650 Q 350 610 465 650 L 465 720 L 235 720 Z','label_x':350,'label_y':684},'sections':sections}
(ROOT/'data/seat-layouts').mkdir(parents=True,exist_ok=True)
(ROOT/'data/seat-layouts/atrium-showroom-luxor.json').write_text(json.dumps(layout,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')

# Static Carrot Top gallery chart generated from the shared room geometry; Reserved 2 is show-specific recommendation.
svg=[]
for s in sections:
    ispick=s['id']=='reserved-2'; stroke='#ffb000' if ispick else 'rgba(255,255,255,.30)'; sw='4' if ispick else '2'
    for rr in s['row_slabs']:
        svg.append(f'<path d="{rr["path"]}" fill="{s["color"]}" stroke="{stroke}" stroke-width="{sw}"/>')
        # letter near left edge, derived from row geometry settings
        y,w,h,b=settings[rr['label']]; svg.append(f'<text x="{350-w/2+16:.1f}" y="{y+h/2-5:.1f}" fill="#fff" font-family="Inter,Arial,sans-serif" font-size="13" font-weight="800">{rr["label"]}</text>')
labels={'reserved-1':(350,520),'reserved-2':(350,315),'reserved-3':(350,112),'reserved-4':(350,52)}
for s in sections:
    x,y=labels[s['id']]; svg.append(f'<text x="{x}" y="{y}" fill="#fff" font-family="Inter,Arial,sans-serif" font-size="20" font-weight="900" text-anchor="middle">{s["label"]}</text>')
static=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 790" role="img" aria-labelledby="title desc"><title id="title">Atrium Showroom seating chart for Carrot Top</title><desc id="desc">Atrium Showroom at Luxor seating layout with Reserved 1 through Reserved 4. Reserved 2 is marked as the Vegas Sidekick Sweet Spot and Our Pick for Carrot Top.</desc><defs><radialGradient id="bg" cx="50%" cy="35%" r="72%"><stop offset="0" stop-color="#241047"/><stop offset="1" stop-color="#08070d"/></radialGradient></defs><rect width="700" height="790" rx="28" fill="url(#bg)"/><text x="28" y="32" fill="#fff" font-family="Inter,Arial,sans-serif" font-size="15" font-weight="900">VEGAS <tspan fill="#ff2e7e">SIDEKICK</tspan></text><text x="28" y="54" fill="#bdb3c8" font-family="Inter,Arial,sans-serif" font-size="10" font-weight="800" letter-spacing="1.6">ATRIUM SHOWROOM · LUXOR</text>{''.join(svg)}<path d="{layout['stage']['path']}" fill="#111116" stroke="#ffb000" stroke-width="3"/><text x="350" y="684" fill="#fff" font-family="Inter,Arial,sans-serif" font-size="24" font-weight="900" text-anchor="middle" letter-spacing="3">STAGE</text><rect x="202" y="738" width="296" height="32" rx="16" fill="#ffb000"/><text x="350" y="759" fill="#171225" font-family="Inter,Arial,sans-serif" font-size="11" font-weight="900" text-anchor="middle" letter-spacing="1.3">RESERVED 2 · SWEET SPOT / OUR PICK</text></svg>'''
(ROOT/'images/carrot-top-atrium-showroom-seating-chart.svg').write_text(static,encoding='utf-8')

css=r'''.atrium-seat-guide{--atrium-amber:#ffb000;display:grid;grid-template-columns:minmax(0,1.2fr) minmax(280px,.8fr);gap:22px;align-items:start;margin-top:24px}.atrium-map-shell{border-radius:28px;padding:18px;background:radial-gradient(circle at 50% 25%,rgba(124,58,237,.22),transparent 32%),linear-gradient(180deg,#160a29,#08070d);border:1px solid rgba(255,255,255,.16);box-shadow:0 24px 60px rgba(13,4,24,.28)}.atrium-map-shell svg{display:block;width:100%;height:auto}.atrium-zone{cursor:pointer;outline:none}.atrium-zone path{fill:var(--zone);stroke:rgba(255,255,255,.26);stroke-width:2;transition:.18s}.atrium-zone.is-pick path{stroke:rgba(255,176,0,.82);stroke-width:3}.atrium-zone:hover path,.atrium-zone:focus path{filter:brightness(1.12);stroke:#fff;stroke-width:4}.atrium-zone.is-active path{stroke:var(--atrium-amber);stroke-width:6;filter:drop-shadow(0 0 9px rgba(255,176,0,.68))}.atrium-zone text{fill:#fff;font:900 18px Inter,Arial,sans-serif;text-anchor:middle;pointer-events:none;text-shadow:0 2px 4px rgba(0,0,0,.5)}.atrium-row-label{font-size:12px!important;text-anchor:start!important}.atrium-stage{fill:#111116;stroke:#ffb000;stroke-width:3}.atrium-stage-label{fill:#fff;font:900 22px Inter,Arial,sans-serif;text-anchor:middle;letter-spacing:.16em}.atrium-map-caption{text-align:center;margin:12px 0 2px}.atrium-map-caption strong{display:block;color:#fff;font-size:1.2rem}.atrium-map-caption span{display:block;color:rgba(255,255,255,.7);font-size:.88rem;margin-top:4px}.atrium-detail{padding:20px;border-radius:20px;background:#fff;border:1px solid #e8e2ed;color:#21182a;box-shadow:0 12px 30px rgba(17,4,28,.08)}.atrium-detail .tag{display:inline-block;font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;font-weight:900;color:#171225;background:#ffb000;padding:5px 8px;border-radius:999px}.atrium-detail h3{margin:9px 0 8px;font-size:1.5rem}.atrium-detail p{margin:0 0 16px;color:#5e5366;line-height:1.55}.atrium-detail .cta{width:100%;justify-content:center}.atrium-chart-gallery{position:relative}.atrium-chart-gallery:after{content:"Seating chart";position:absolute;left:12px;bottom:12px;padding:6px 9px;border-radius:999px;background:rgba(13,7,20,.84);color:#fff;font-size:.72rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;pointer-events:none}.atrium-chart-gallery img{object-fit:contain!important;background:#09060f}#photos .gallery.gallery-4{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr));height:560px}#photos .gallery.gallery-4 button{min-width:0;min-height:0}#photos .gallery.gallery-4 img{width:100%;height:100%;object-fit:cover}.atrium-mobile-popover{display:none}.atrium-lb-nav{position:absolute!important;top:50%!important;transform:translateY(-50%);z-index:3;width:52px!important;height:52px!important;border-radius:50%!important;background:rgba(255,255,255,.94)!important;color:#17082e!important;font-size:2rem!important}.atrium-lb-prev{left:18px!important;right:auto!important}.atrium-lb-next{right:18px!important}.atrium-lb-count{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);z-index:3;background:rgba(23,8,46,.82);color:#fff;padding:6px 11px;border-radius:999px;font-size:.8rem;font-weight:800}.video-shell{max-width:900px;margin-top:24px}.video{aspect-ratio:16/9;position:relative;border-radius:18px;overflow:hidden;background:#000}.video img,.video iframe{width:100%;height:100%;object-fit:cover;border:0}.video .play{position:absolute;inset:0;border:0;background:rgba(0,0,0,.25);display:grid;place-items:center;color:#171225;cursor:pointer}.video .play span{width:76px;height:76px;border-radius:50%;background:#ffb000;display:grid;place-items:center;font-size:2rem;font-weight:900}@media(max-width:820px){.atrium-seat-guide{grid-template-columns:1fr}.atrium-map-shell{padding:10px}.atrium-detail{display:none}.atrium-mobile-popover{position:fixed;z-index:1100;left:14px;right:14px;bottom:98px;display:flex;padding:14px 48px 14px 15px;border:1px solid rgba(255,176,0,.65);border-radius:16px;background:rgba(20,9,35,.97);box-shadow:0 14px 38px rgba(0,0,0,.38);color:#fff;opacity:0;pointer-events:none;transform:translateY(16px);transition:.2s}.atrium-mobile-popover.is-open{opacity:1;pointer-events:auto;transform:none}.atrium-mobile-popover strong{display:block;margin:4px 0}.atrium-mobile-popover p{margin:0;color:#ddd4e4;font-size:.82rem;line-height:1.45}.atrium-mobile-popover>button{position:absolute;right:9px;top:8px;width:30px;height:30px;border:0;border-radius:50%;background:rgba(255,255,255,.1);color:#fff;font-size:1.2rem}#photos .gallery.gallery-4{height:auto;grid-template-columns:1fr;grid-template-rows:auto}#photos .gallery.gallery-4 img{aspect-ratio:4/3}.atrium-chart-gallery img{object-fit:contain!important;aspect-ratio:4/3}.atrium-lb-count{bottom:100px}}@media(prefers-reduced-motion:reduce){.atrium-zone path,.atrium-mobile-popover{transition:none}}'''
(ROOT/'assets/seat-layouts').mkdir(parents=True,exist_ok=True)
(ROOT/'assets/seat-layouts/atrium-showroom-luxor.css').write_text(css+'\n',encoding='utf-8')

js=r'''(()=>{const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));async function mount(root){const data=await fetch(root.dataset.layoutUrl,{credentials:'same-origin'}).then(r=>r.json());const sweet=root.dataset.sweetSpot,copy=root.dataset.sweetCopy,ticket=root.dataset.ticketUrl,by=Object.fromEntries(data.sections.map(s=>[s.id,s]));const row=(r,s)=>`<path d="${esc(r.path)}"></path>`;const zone=s=>{const active=s.id===sweet;return `<g class="atrium-zone${active?' is-pick':''}" data-zone="${s.id}" role="button" tabindex="0" aria-label="${esc(s.label)}${active?', Sweet Spot / Our Pick':''}" style="--zone:${s.color}">${s.row_slabs.map(r=>row(r,s)).join('')}<text x="350" y="${s.id==='reserved-1'?520:s.id==='reserved-2'?315:s.id==='reserved-3'?112:52}">${esc(s.label)}</text></g>`};root.innerHTML=`<div><div class="atrium-map-shell"><svg viewBox="${data.viewBox}" role="img" aria-label="Atrium Showroom at Luxor seating layout">${data.sections.map(zone).join('')}<path class="atrium-stage" d="${data.stage.path}"></path><text class="atrium-stage-label" x="${data.stage.label_x}" y="${data.stage.label_y}">STAGE</text></svg><div class="atrium-map-caption"><strong>${esc(data.venue)}</strong><span>${esc(data.address)}</span></div></div></div><div><div class="atrium-detail" aria-live="polite"><span class="tag">Sweet spot</span><h3>Reserved 2</h3><p>${esc(copy)}</p><a class="cta vs-ticket-primary" href="${esc(ticket)}" target="_blank" rel="noopener sponsored">Check seats →</a></div></div><div class="atrium-mobile-popover" aria-live="polite"><div><span class="tag">Sweet spot</span><strong>Reserved 2</strong><p>${esc(copy)}</p></div><button type="button" aria-label="Close seat description">×</button></div>`;const detail=root.querySelector('.atrium-detail'),pop=root.querySelector('.atrium-mobile-popover');function activate(id,showPop=false){const s=by[id];if(!s)return;root.querySelectorAll('[data-zone]').forEach(el=>el.classList.toggle('is-active',el.dataset.zone===id));const isSweet=id===sweet,text=isSweet?copy:s.description,tag=isSweet?'Sweet spot':'Section';detail.querySelector('.tag').textContent=tag;detail.querySelector('h3').textContent=s.label;detail.querySelector('p').textContent=text;pop.querySelector('.tag').textContent=tag;pop.querySelector('strong').textContent=s.label;pop.querySelector('p').textContent=text;if(showPop&&matchMedia('(max-width:820px)').matches)pop.classList.add('is-open')}root.addEventListener('click',e=>{const z=e.target.closest('[data-zone]');if(z)activate(z.dataset.zone,true);if(e.target.closest('.atrium-mobile-popover>button'))pop.classList.remove('is-open')});root.addEventListener('keydown',e=>{const z=e.target.closest('[data-zone]');if(z&&(e.key==='Enter'||e.key===' ')){e.preventDefault();activate(z.dataset.zone,true)}});addEventListener('scroll',()=>pop.classList.remove('is-open'),{passive:true});activate(sweet)}function gallery(){const buttons=[...document.querySelectorAll('#photos .gallery button')],light=document.getElementById('lightbox');if(!buttons.length||!light)return;const img=light.querySelector('#lightboxImg, img');if(!img)return;let current=0,touchX=null,prev=document.createElement('button'),next=document.createElement('button'),count=document.createElement('div');prev.type=next.type='button';prev.className='atrium-lb-nav atrium-lb-prev';next.className='atrium-lb-nav atrium-lb-next';prev.setAttribute('aria-label','Previous photo');next.setAttribute('aria-label','Next photo');prev.textContent='‹';next.textContent='›';count.className='atrium-lb-count';light.append(prev,next,count);const show=i=>{current=(i+buttons.length)%buttons.length;const th=buttons[current].querySelector('img');img.src=th.currentSrc||th.src;img.alt=th.alt||'Carrot Top photo';count.textContent=`${current+1} of ${buttons.length}`};buttons.forEach((b,i)=>b.addEventListener('click',()=>show(i)));prev.addEventListener('click',e=>{e.stopPropagation();show(current-1)});next.addEventListener('click',e=>{e.stopPropagation();show(current+1)});addEventListener('keydown',e=>{if(!light.classList.contains('open'))return;if(e.key==='ArrowLeft')show(current-1);if(e.key==='ArrowRight')show(current+1)});light.addEventListener('touchstart',e=>touchX=e.changedTouches[0]?.clientX??null,{passive:true});light.addEventListener('touchend',e=>{if(touchX==null)return;const dx=(e.changedTouches[0]?.clientX??touchX)-touchX;touchX=null;if(Math.abs(dx)>45)show(current+(dx<0?1:-1))},{passive:true})}document.querySelectorAll('[data-seat-layout="atrium-showroom-luxor"]').forEach(mount);gallery();const v=document.querySelector('[data-youtube-id]');if(v){v.querySelector('.play')?.addEventListener('click',()=>{const id=v.dataset.youtubeId;v.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1" title="Official Carrot Top trailer" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`})}})();'''
(ROOT/'assets/seat-layouts/atrium-showroom-luxor.js').write_text(js+'\n',encoding='utf-8')

# Existing FAQs stay intact unless their JSON was invalid; only the page system is rebuilt.
def faq_html(obj):
    bits=[]
    for q in obj.get('mainEntity',[]):
        qu=html.escape(q.get('name','')); ans=html.escape(q.get('acceptedAnswer',{}).get('text',''))
        bits.append(f'<details><summary>{qu}</summary><div>{ans}</div></details>')
    return ''.join(bits)
faq_visible=faq_html(faq)
faq_json=json.dumps(faq,ensure_ascii=False,separators=(',',':'))
if video:
    video['description']=video.get('description','').replace('Atrium Showroom inside the Luxor Hotel','Atrium Showroom at Luxor').replace('Atrium Showroom, Luxor Hotel','Atrium Showroom at Luxor')
    video_json=f'<script type="application/ld+json">{json.dumps(video,ensure_ascii=False,separators=(",",":"))}</script>'
else: video_json=''

byday=[]; common=[]
spot=rec.get('spotlight',{})
for day,times in spot.get('schedule_days',{}).items():
    if times: byday.append('https://schema.org/'+day); common+=times
schedule_obj=None
if byday and common and len(set(common))==1:
    tm=common[0].replace(' PM','').replace(' AM',''); h,m=(tm.split(':')+['00'])[:2]; hh=int(h)+(12 if 'PM' in common[0] and int(h)!=12 else 0); schedule_obj={'@type':'Schedule','byDay':byday,'startTime':f'{hh:02d}:{int(m):02d}'}
event={'@context':'https://schema.org','@type':'EventSeries','name':'Carrot Top at Luxor Las Vegas','description':'A 75-minute prop-comedy residency at Luxor Las Vegas, with fast visual jokes and handmade props.','image':['https://vegassidekick.com/images/carrot-top-show-2.jpg','https://vegassidekick.com/images/carrot-top-show-3.jpg','https://vegassidekick.com/images/carrot-top-hero.jpg'],'url':'https://vegassidekick.com/shows/comedy/carrot-top/','eventStatus':'https://schema.org/EventScheduled','eventAttendanceMode':'https://schema.org/OfflineEventAttendanceMode','organizer':{'@type':'Organization','name':VENUE,'url':'https://vegassidekick.com/shows/comedy/carrot-top/'},'location':{'@type':'Place','name':VENUE,'address':{'@type':'PostalAddress','streetAddress':'3900 S Las Vegas Blvd','addressLocality':'Las Vegas','addressRegion':'NV','postalCode':'89119','addressCountry':'US'}},'performer':{'@type':'Person','name':'Carrot Top'},'offers':{'@type':'Offer','price':price,'priceCurrency':'USD','availability':'https://schema.org/InStock','url':ticket,'validFrom':'2026-01-01'},'duration':f'PT{runtime}M','audience':{'@type':'Audience','audienceType':'Ages 16 and up.'},'@id':'https://vegassidekick.com/shows/comedy/carrot-top/#event'}
if schedule_obj: event['eventSchedule']=schedule_obj
bread={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://vegassidekick.com/'},{'@type':'ListItem','position':2,'name':'Comedy','item':'https://vegassidekick.com/shows/comedy/'},{'@type':'ListItem','position':3,'name':'Carrot Top','item':'https://vegassidekick.com/shows/comedy/carrot-top/'}]}
webpage={'@context':'https://schema.org','@type':'WebPage','url':'https://vegassidekick.com/shows/comedy/carrot-top/','dateModified':DATE,'lastReviewed':DATE,'author':{'@type':'Person','@id':'https://vegassidekick.com/about/kris-kidd/#kris','name':'Kris Kidd','url':'https://vegassidekick.com/about/kris-kidd/','image':'https://vegassidekick.com/images/kris-kidd.webp'},'mainEntity':{'@id':'https://vegassidekick.com/shows/comedy/carrot-top/#event'}}

def j(x): return json.dumps(x,ensure_ascii=False,separators=(',',':'))
regline=f'<div class="vs-deal-line"><span class="vs-regular-price">Regular ${regular}</span><span class="vs-save-badge">Save ${regular-price}</span></div>' if regular else ''
# Schedule grid from verified source data.
order=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']; ab={'Monday':'Mon','Tuesday':'Tue','Wednesday':'Wed','Thursday':'Thu','Friday':'Fri','Saturday':'Sat','Sunday':'Sun'}
days=[]
for d in order:
    times=spot.get('schedule_days',{}).get(d,[]); val=' & '.join(times) if times else 'Dark'
